-- =========================================================
-- 회계 학습 플랫폼 통합 DB 구축 스크립트 (MariaDB 호환)
-- phpMyAdmin SQL 탭에 붙여넣어 실행하거나 CLI에서 임포트
-- =========================================================

SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
START TRANSACTION;
SET time_zone = "+09:00";

-- ---------------------------------------------------------
-- 1. 회원(Users) 테이블
-- ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS `users` (
  `id`            int(11)             NOT NULL AUTO_INCREMENT,
  `username`      varchar(50)         NOT NULL                        COMMENT '로그인 아이디',
  `password_hash` varchar(255)        NOT NULL                        COMMENT '암호화된 비밀번호',
  `role`          enum('user','admin') DEFAULT 'user'                 COMMENT '회원 등급',
  `is_blocked`    tinyint(1)          DEFAULT 0                       COMMENT '차단 여부 (0:정상, 1:차단)',
  `block_reason`  varchar(255)        DEFAULT NULL                    COMMENT '차단 사유 메모',
  `created_at`    datetime            DEFAULT current_timestamp()     COMMENT '가입일',
  `last_login_at` datetime            DEFAULT NULL                    COMMENT '최근 로그인 일시',
  `last_login_ip` varchar(45)         DEFAULT NULL                    COMMENT '최근 접속 IP',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_username` (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='회원 기본 정보 테이블';

-- ---------------------------------------------------------
-- 2. 사용자 활동 로그(user_logs) 테이블
-- ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS `user_logs` (
  `id`         int(11)      NOT NULL AUTO_INCREMENT,
  `user_id`    int(11)      NOT NULL                        COMMENT 'users.id 참조',
  `action`     varchar(50)  NOT NULL                        COMMENT '행동 구분 (login, solve_quiz, watch_video 등)',
  `detail`     text         DEFAULT NULL                    COMMENT '상세 내용(JSON 또는 설명)',
  `created_at` datetime     DEFAULT current_timestamp()     COMMENT '발생 일시',
  PRIMARY KEY (`id`),
  KEY `idx_user_action` (`user_id`, `action`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='사용자 활동 감사 로그';

-- ---------------------------------------------------------
-- 3. 다운로드 감사 로그(download_logs) 테이블
-- ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS `download_logs` (
  `id`            int(11)      NOT NULL AUTO_INCREMENT,
  `user_id`       int(11)      DEFAULT NULL                    COMMENT 'users.id 참조',
  `file_path`     varchar(255) NOT NULL                        COMMENT '다운로드된 파일 경로',
  `ip_address`    varchar(45)  DEFAULT NULL                    COMMENT '요청 IP',
  `downloaded_at` datetime     DEFAULT current_timestamp()     COMMENT '다운로드 일시',
  PRIMARY KEY (`id`),
  KEY `idx_user_file` (`user_id`, `file_path`),
  KEY `idx_downloaded_at` (`downloaded_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='다운로드 이력';

-- ---------------------------------------------------------
-- 4. 학습 통계(learning_stats) 테이블
-- ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS `learning_stats` (
  `id`           int(11)     NOT NULL AUTO_INCREMENT,
  `user_id`      int(11)     NOT NULL                        COMMENT 'users.id 참조',
  `solved_count` int(11)     DEFAULT 0                       COMMENT '푼 문제 수',
  `correct_count` int(11)    DEFAULT 0                       COMMENT '맞힌 문제 수',
  `video_seconds` int(11)    DEFAULT 0                       COMMENT '영상 시청 초 합계',
  `updated_at`   datetime    DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_user_id` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='학습 요약 통계';

-- ---------------------------------------------------------
-- 5. 퀴즈 문제 통합 DB (quiz_questions) 테이블
-- ---------------------------------------------------------
CREATE TABLE IF NOT EXISTS `quiz_questions` (
  `id`               int(11) NOT NULL AUTO_INCREMENT,
  `grade`            varchar(20) NOT NULL COMMENT '등급 (grade1, grade2)',
  `category`         varchar(50) NOT NULL COMMENT '구분 (기출문제, 전산회계책 등)',
  `type`             varchar(20) NOT NULL COMMENT '유형 (journal, theory)',
  `file_key`         varchar(100) NOT NULL COMMENT '소스 엑셀 파일명',
  `question_no`      int(11) NOT NULL COMMENT '문제 번호',
  `tag_key`          varchar(100) DEFAULT NULL COMMENT '문제 태그/출처',
  `question`         text NOT NULL COMMENT '문제 본문',
  `difficulty`       varchar(20) DEFAULT '보통' COMMENT '난이도',
  `subject_category` varchar(50) DEFAULT '일반' COMMENT '세부 과목/단원',
  `option_1`         text DEFAULT NULL COMMENT '보기1 (필기 전용)',
  `option_2`         text DEFAULT NULL COMMENT '보기2 (필기 전용)',
  `option_3`         text DEFAULT NULL COMMENT '보기3 (필기 전용)',
  `option_4`         text DEFAULT NULL COMMENT '보기4 (필기 전용)',
  `correct_option`   tinyint(4) DEFAULT NULL COMMENT '정답 번호 (1~4)',
  `journal_debit`    longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '차변 정답 JSON' CHECK (json_valid(`journal_debit`)),
  `journal_credit`   longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '대변 정답 JSON' CHECK (json_valid(`journal_credit`)),
  `explanation`      text DEFAULT NULL COMMENT '해설 텍스트',
  `is_verified`      tinyint(1) DEFAULT 1 COMMENT '검증 완료 여부',
  `created_at`       datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_file_qno` (`file_key`, `question_no`),
  KEY `idx_grade_type` (`grade`, `type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='회계 퀴즈 통합 문제은행';

