[답] ②
ㆍ원가 배분의 지침이 되는 기준은 다음과 같다.
(1) 인과관계 기준：배분하려고 하는 원가의 발생과 원가대상 사이의 인과관계가 존재할 경우 이러한 인과
관계에 따라 원가를 배분하는 방법으로 인과관계에 따라 원가 배분이 경제적으로 실현가능한 경우에는 
인과관계기준에 의해 원가를 배분해야 하며 이는 가장 이상적인 원가 배분기준이 된다.
(2) 수혜기준：배분하려고 하는 원가로부터 원가대상에 제공된 경제적 효익을 측정할 수 있는 경우 이러한 
경제적 효익의 크기에 따라 원가를 배분하는 기준을 말한다.
(3) 부담능력기준：원가대상이 원가를 부담할 수 있는 능력에 따라 원가를 배분하는 기준이다.
(4) 공정성과 공평성 기준：원가대상에 원가를 배분할 때에는 공정하고 공평하게 해야 한다는 기준이다. 
일반적으로 공정성과 공평성은 매우 포괄적인 개념이기 때문에 원가 배분을 위한 구체적인 기준이라기
보다는 그 자체가 원가 배분을 통해 달성하고자 하는 목표에 해당한다.', 1),
