부동산 임대차(월세) 계약서
본 부동산에 대하여 임대인과 임차인 쌍방은 다음과 같이 합의하여 임대차(월세)계약을 체결한다.
1. 부동산의 표시
소 재 지 서울특별시 강남구 논현로 56
건 물 구조 철근콘크리트 용도 사무실 면적 100㎡
임 대 부 분상동 소재지 전부
2. 계약내용
제 1 조 위 부동산의 임대차계약에 있어 임차인은 보증금 및 차임을 아래와 같이 지불하기로 한다.
보증금 일금 일억팔천만 원정 (￦ 180,000,000)
차 임 일금 팔십만 원정 (￦ 800,000)은 매월 말일에 지불한다.
제 2 조 임대인은 위 부동산을 임대차 목적대로 사용·수익할 수 있는 상태로 하여 2025년 07월 14일까지 
임차인에게 인도하며, 임대차 기간은 인도일로부터 12개월로 한다.
