■ 소모품 구입시 자산으로 처리한 경우 사용한 금액을 소모품비(비용)으로 처리한다. 

소모품비 = 기초잔액 500,000원 + 당기구입액 200,000원 - 기말잔액 300,000원 = 400,000원
[4] 자동결산 - 결산자료입력
■ 외상매출금 : 154,070,000원 × 2 % - 0원 = 3,081,400원
■ 받을어음 : 100,000,000원 × 2 % - 650,000원 = 1,350,000원
방법  1  : 결산자료입력 메뉴의 상단 [대손상각] 버튼을 클릭하여 “대손율(%) : 2 %”을 입력하고 외상매출금과 받을
어음을 제외한 이외의 계정과목에 대한 “추가설정액”란의 금액은 삭제한 후 [결산반영] 버튼을 누른다. 
“결산반영금액”란에 금액을 반영하고 [전표추가] 버튼을 클릭하여 일반전표에 전표를 추가한다.
방법 2 : 결산자료입력 메뉴의 대손상각에 [외상매출금 : 3,081,400원, 받을어음 : 1,350,000원]을 입력한 후 결산
자료 입력의 [전표추가] 버튼을 클릭하여 일반전표에 전표를 추가한다.
방법 3 : 결산일(12월 31일)에 일반전표입력에 직접 입력
