방법  1  : 결산자료입력 메뉴의 상단 [대손상각] 버튼을 클릭하여 “대손율(%) : 1 %”을 입력하고 외상매출금과 받을
어음을 제외한 이외의 계정과목에 대한 “추가설정액”란의 금액은 삭제한 후 [결산반영] 버튼을 눌러 “결
산반영금액”란에 반영하여 전표추가를 한다.
방법 2 : 결산자료입력 메뉴의 대손상각에 [외상매출금 : 323,500원, 받을어음 : 240,000원]을 입력한 후 결산자
료 입력의 전표추가를 한다.
